    '— none (top level) —' => '— keine (oberste Ebene) —',
    'A subpage has an address under its parent (/services/kitchens) and appears in its breadcrumbs.' => 'Eine Unterseite hat ihre Adresse unterhalb der übergeordneten Seite (/leistungen/kuechen) und erscheint in deren Brotkrumen-Navigation.',
    'Publish the hidden page automatically at:' => 'Verborgene Seite automatisch veröffentlichen am:',
    'Text history (%s)' => 'Textverlauf (%s)',
    'Restore this version of the text? The current version stays in the history.' => 'Diese Version des Textes wiederherstellen? Die aktuelle Version bleibt im Verlauf erhalten.',
