    'you have been given access to the administration of the website %s. Your username is %s.' => 'Sie haben Zugang zur Administration der Website %s erhalten. Ihr Benutzername lautet %s.',
    'Set your password at this address (valid for 3 days, single use):' => 'Legen Sie Ihr Passwort unter dieser Adresse fest (3 Tage gültig, einmalig verwendbar):',
