    'The file has been replaced – the new version is shown everywhere it is used.' => 'Die Datei wurde ersetzt – die neue Version wird überall angezeigt, wo sie verwendet wird.',
    'Enquiries deleted: %d.' => 'Gelöschte Anfragen: %d.',
    'Enquiries resolved: %d.' => 'Erledigte Anfragen: %d.',
    'The note has been saved.' => 'Die Notiz wurde gespeichert.',
    'The attachment no longer exists.' => 'Der Anhang existiert nicht mehr.',
    'The user has been created and the invitation sent to %s.' => 'Der Benutzer wurde angelegt und die Einladung an %s gesendet.',
    'The new password link has been sent to %s.' => 'Der Link für ein neues Passwort wurde an %s gesendet.',
    'The user has no e-mail or is blocked.' => 'Der Benutzer hat keine E-Mail-Adresse oder ist gesperrt.',
    'This site requires two-factor sign-in. Please turn it on below – until then the administration is locked.' => 'Diese Website erfordert die Zwei-Faktor-Anmeldung. Bitte aktivieren Sie sie unten – bis dahin ist die Administration gesperrt.',
    'In the past week, visitors repeatedly could not find %d addresses (404 error). Redirect them to the right pages.' => 'In der vergangenen Woche konnten Besucher wiederholt %d Adressen nicht finden (404-Fehler). Leiten Sie sie auf die richtigen Seiten weiter.',
