    'Up to %d MB: PDF, image, document or ZIP.' => 'Bis zu %d MB: PDF, Bild, Dokument oder ZIP.',
    'Sample item' => 'Beispieleintrag',
    'attachment (file)' => 'Anhang (Datei)',
    'Two-factor sign-in' => 'Zwei-Faktor-Anmeldung',
    'required for administrators' => 'für Administratoren erforderlich',
    'required for all users' => 'für alle Benutzer erforderlich',
    'Save changes' => 'Änderungen speichern',
    'Mine' => 'Meine',
    'Edit' => 'Bearbeiten',
    'The SVG file could not be read (max. 2 MB, valid SVG).' => 'Die SVG-Datei konnte nicht gelesen werden (max. 2 MB, gültiges SVG).',
    'Only a JPG, PNG or WebP image can be replaced.' => 'Nur ein JPG-, PNG- oder WebP-Bild kann ersetzt werden.',
    'An invitation needs an e-mail.' => 'Für eine Einladung wird eine E-Mail-Adresse benötigt.',
    'The new name must be unused and written in lowercase without accents (e.g. card-large).' => 'Der neue Name darf noch nicht vergeben sein und muss in Kleinbuchstaben ohne Akzente geschrieben werden (z. B. card-large).',
    'A few short steps and your website is running. Everything can be changed later in the administration.' => 'Ein paar kurze Schritte, und Ihre Website läuft. Alles lässt sich später in der Administration ändern.',
    'What you want switched on' => 'Was Sie aktivieren möchten',
    'Extensions can be switched on or off at any time in the administration (Extensions). Switching off deletes nothing.' => 'Erweiterungen können Sie jederzeit in der Administration (Erweiterungen) ein- oder ausschalten. Durch das Ausschalten wird nichts gelöscht.',
    'News and blog: the /novinky listing with categories and tags, RSS, the News element in the builder and a link in the automatic menu.' => 'News und Blog: die Übersicht /novinky mit Kategorien und Schlagwörtern, RSS, das Element „News“ im Builder und ein Link im automatischen Menü.',
    'Forms and enquiries' => 'Formulare und Anfragen',
    'The Form element in the builder and the Enquiries inbox: submitted enquiries are stored, arrive by e-mail and can be passed to a colleague or a CRM.' => 'Das Element „Formular“ im Builder und der Posteingang „Anfragen“: Gesendete Anfragen werden gespeichert, kommen per E-Mail an und können an einen Kollegen oder ein CRM weitergegeben werden.',
    '%s – the extension is switched off and will not appear on the website.' => '%s – die Erweiterung ist ausgeschaltet und erscheint nicht auf der Website.',
    'News is switched off on this website.' => 'News sind auf dieser Website ausgeschaltet.',
    'Search the website…' => 'Website durchsuchen …',
    'Search the website' => 'Website durchsuchen',
    'out of 5 · 120 reviews' => 'von 5 · 120 Bewertungen',
    'Back-to-top button (bottom right on the website)' => 'Button „Nach oben“ (unten rechts auf der Website)',
    'Back to top' => 'Nach oben',
    'Subscribe' => 'Abonnieren',
    'We only send news and offers. You can unsubscribe with one click in every e-mail.' => 'Wir senden nur News und Angebote. Sie können sich mit einem Klick in jeder E-Mail abmelden.',
    'Thank you! We have sent you an e-mail with a link – click it to confirm your subscription.' => 'Vielen Dank! Wir haben Ihnen eine E-Mail mit einem Link gesendet – klicken Sie darauf, um Ihr Abonnement zu bestätigen.',
    'Please check the e-mail address.' => 'Bitte überprüfen Sie die E-Mail-Adresse.',
    'Too many attempts in a row. Please try again in a moment.' => 'Zu viele Versuche hintereinander. Bitte versuchen Sie es gleich noch einmal.',
    'Your e-mail' => 'Ihre E-Mail-Adresse',
    'you@example.com' => 'sie@beispiel.de',
    'The event is on now.' => 'Die Veranstaltung läuft gerade.',
    'Enter the date as YYYY-MM-DD HH:MM.' => 'Geben Sie das Datum im Format JJJJ-MM-TT HH:MM ein.',
    'days' => 'Tage',
    'minutes' => 'Minuten',
    'seconds' => 'Sekunden',
    'Projects delivered on time' => 'Pünktlich abgeschlossene Projekte',
    'Returning customers' => 'Stammkunden',
    'Rated %s out of 5' => 'Bewertet mit %s von 5',
    'Confirm your subscription – %s' => 'Bestätigen Sie Ihr Abonnement – %s',
    'to confirm your subscription to news from %s, click the link:' => 'um Ihr Abonnement der News von %s zu bestätigen, klicken Sie auf den Link:',
    'If you did not ask to subscribe, ignore this e-mail – without confirmation we will not send you anything.' => 'Wenn Sie kein Abonnement angefordert haben, ignorieren Sie diese E-Mail – ohne Bestätigung senden wir Ihnen nichts.',
    'Subscription confirmed' => 'Abonnement bestätigt',
    'Thank you, we will send news to %s. You can unsubscribe using the link in every e-mail.' => 'Vielen Dank, wir senden News an %s. Sie können sich über den Link in jeder E-Mail abmelden.',
    'Unsubscribed' => 'Abgemeldet',
    'We have removed %s from the subscriber list.' => 'Wir haben %s aus der Abonnentenliste entfernt.',
    'The link is invalid or has already been used. If you want to receive news, please subscribe again.' => 'Der Link ist ungültig oder wurde bereits verwendet. Wenn Sie News erhalten möchten, abonnieren Sie bitte erneut.',
    'Preview size' => 'Vorschaugröße',
    'Fit' => 'Anpassen',
    'Wide monitor (1920 px)' => 'Breiter Monitor (1920 px)',
    'Help and keyboard shortcuts (?)' => 'Hilfe und Tastenkürzel (?)',
    'Help' => 'Hilfe',
    'Text “%s” has low contrast against its background (%d : 1) – it is hard to read.' => 'Der Text „%s“ hat einen geringen Kontrast zum Hintergrund (%d : 1) – er ist schwer lesbar.',
    'Save draft' => 'Entwurf speichern',
    'Undo / redo' => 'Rückgängig / Wiederholen',
    'Duplicate the selected element' => 'Ausgewähltes Element duplizieren',
