    'Save and continue' => 'Speichern und fortfahren',
    'Save details' => 'Daten speichern',
    'Save your backup codes – each works once when you do not have your phone. They will not be shown again.' => 'Speichern Sie Ihre Backup-Codes – jeder funktioniert einmal, wenn Sie Ihr Smartphone nicht zur Hand haben. Sie werden nicht erneut angezeigt.',
    'In Claude Code, run:' => 'Führen Sie in Claude Code Folgendes aus:',
    'Publishing' => 'Veröffentlichung',
    'Turn off two-factor sign-in' => 'Zwei-Faktor-Anmeldung deaktivieren',
    'Create token' => 'Token erstellen',
    'Enter the six-digit code from your authenticator app. No phone? Use one of your backup codes.' => 'Geben Sie den sechsstelligen Code aus Ihrer Authenticator-App ein. Kein Smartphone zur Hand? Verwenden Sie einen Ihrer Backup-Codes.',
    'Turn on two-factor sign-in' => 'Zwei-Faktor-Anmeldung aktivieren',
    'Classification' => 'Einordnung',
    'Copy it now – it will not be shown again.' => 'Kopieren Sie es jetzt – es wird nicht erneut angezeigt.',
    'Back to the dashboard' => 'Zurück zum Dashboard',
