    'created from the headline' => 'aus der Überschrift erstellt',
    'Your account is protected by a password only. With two-factor sign-in, nobody can sign in without your phone – even if they guess or steal the password.' => 'Ihr Konto ist nur durch ein Passwort geschützt. Mit der Zwei-Faktor-Anmeldung kann sich ohne Ihr Smartphone niemand anmelden – auch wenn er das Passwort errät oder stiehlt.',
    'AI search engines and assistants' => 'KI-Suchmaschinen und Assistenten',
    'System update' => 'Systemupdate',
    'Update the system? A database backup will be created first. The site will be unavailable for a few seconds.' => 'System aktualisieren? Zuvor wird ein Datenbank-Backup erstellt. Die Website ist für einige Sekunden nicht erreichbar.',
