    'Reply by email' => 'Per E-Mail antworten',
    'Reopen' => 'Wieder öffnen',
    'Really delete this enquiry?' => 'Diese Anfrage wirklich löschen?',
    'The enquiry is resolved.' => 'Die Anfrage ist erledigt.',
    'The enquiry is open again.' => 'Die Anfrage ist wieder offen.',
    'The enquiry was deleted.' => 'Die Anfrage wurde gelöscht.',
    'Form name (in Enquiries and in the email)' => 'Formularname (in Anfragen und in der E-Mail)',
    'Form fields' => 'Formularfelder',
    'Required' => 'Pflichtfeld',
    'Choice options (one per line)' => 'Auswahlmöglichkeiten (eine pro Zeile)',
    'Thank-you message' => 'Dankesnachricht',
    'Notification email (empty = site email from Settings)' => 'Benachrichtigungs-E-Mail (leer = E-Mail-Adresse der Website aus den Einstellungen)',
    'Company' => 'Unternehmen',
    'Fill these in once and the site uses them everywhere: in the footer and on the contact page (the Company details element in the builder) and for Google, maps and AI assistants – so they answer correctly when you are open and where to find you.' => 'Füllen Sie dies einmal aus, und die Website verwendet es überall: im Fußbereich und auf der Kontaktseite (das Element Unternehmensdaten im Builder) sowie für Google, Karten und KI-Assistenten – damit diese richtig antworten, wann Sie geöffnet haben und wo man Sie findet.',
    'Registered company name' => 'Eingetragener Firmenname',
    'The exact registered name, e.g. “Novak Joinery Ltd”. Elsewhere the site uses the site name.' => 'Der genaue eingetragene Name, z. B. „Müller Tischlerei GmbH“. An anderen Stellen verwendet die Website den Website-Namen.',
    'Business type' => 'Art des Unternehmens',
    'Search engines show opening hours, a map and reviews depending on the type. If customers visit you, do not choose “company without premises”.' => 'Suchmaschinen zeigen je nach Art Öffnungszeiten, eine Karte und Bewertungen an. Wenn Kunden Sie besuchen, wählen Sie nicht „Unternehmen ohne Geschäftsräume“.',
    'VAT payers only, e.g. CZ12345678.' => 'Nur für umsatzsteuerpflichtige Unternehmen, z. B. DE123456789.',
    'Address and contact' => 'Adresse und Kontakt',
    'Street and number' => 'Straße und Hausnummer',
    'Postcode' => 'Postleitzahl',
    'City' => 'Stadt',
    'Country (code)' => 'Land (Code)',
    'Two-letter code: CZ, SK, DE…' => 'Zweistelliger Code: DE, AT, CH …',
    'Opening hours and map' => 'Öffnungszeiten und Karte',
    'One day or range of days per line: “Mo–Fr 8:00–17:00”, “Sa 9–12”, “Su closed”, lunch break “Tu 8–12, 13–17”. Empty = no opening hours.' => 'Ein Tag oder Tagesbereich pro Zeile: „Mo–Fr 8:00–17:00“, „Sa 9–12“, „So geschlossen“, Mittagspause „Di 8–12, 13–17“. Leer = keine Öffnungszeiten.',
    'Map link' => 'Kartenlink',
    'Link to the place on Mapy.cz or Google Maps – the Company details element turns it into a “Show on map” link.' => 'Link zum Ort auf Mapy.cz oder Google Maps – das Element Unternehmensdaten macht daraus einen Link „Auf Karte anzeigen“.',
    'Coordinates (optional)' => 'Koordinaten (optional)',
    'Latitude and longitude, e.g. 50.0875, 14.4213 – a more precise location for maps and search engines.' => 'Breiten- und Längengrad, z. B. 50.0875, 14.4213 – ein genauerer Standort für Karten und Suchmaschinen.',
    'company without premises for customers' => 'Unternehmen ohne Geschäftsräume für Kunden',
    'business premises (general)' => 'Geschäftsräume (allgemein)',
    'crafts and construction' => 'Handwerk und Bau',
    'professional services (consulting, agency)' => 'professionelle Dienstleistungen (Beratung, Agentur)',
    'legal services' => 'Rechtsdienstleistungen',
    'accounting and tax' => 'Buchhaltung und Steuern',
    'health and care' => 'Gesundheit und Pflege',
    'car service and cars' => 'Autowerkstatt und Autos',
    'restaurant, café' => 'Restaurant, Café',
    'sport and fitness' => 'Sport und Fitness',
    'school and courses' => 'Schule und Kurse',
    'Company details' => 'Firmendaten',
    'Registered name and company ID' => 'Firmenname und USt-IdNr.',
    'Fill in company details' => 'Firmendaten ausfüllen',
    'Address, phone and opening hours appear on the contact page, in the footer and to search engines.' => 'Adresse, Telefonnummer und Öffnungszeiten erscheinen auf der Kontaktseite, im Fußbereich und in den Suchmaschinen.',
    'Collections' => 'Sammlungen',
    'New collection' => 'Neue Sammlung',
    'No collections yet.' => 'Noch keine Sammlungen.',
    'A collection is a list of similar things with their own fields – testimonials, team members, products, branches, a price list. Put them on the site with the Collection list element in the builder; each item can also have its own page.' => 'Eine Sammlung ist eine Liste ähnlicher Dinge mit eigenen Feldern – Kundenstimmen, Teammitglieder, Produkte, Filialen, eine Preisliste. Auf die Website bringen Sie sie mit dem Element „Sammlungsliste“ im Builder; jeder Eintrag kann auch eine eigene Seite haben.',
    'Create a collection' => 'Sammlung anlegen',
    'Items' => 'Einträge',
    'Item pages' => 'Eintragsseiten',
    'Add item' => 'Eintrag hinzufügen',
    'Fields and settings' => 'Felder und Einstellungen',
    'Detail template' => 'Detailvorlage',
    'Detail template (%s)' => 'Detailvorlage (%s)',
    'Collection name' => 'Name der Sammlung',
    'e.g. Testimonials, Team, Products' => 'z. B. Kundenstimmen, Team, Produkte',
    'From the name if left empty. Item pages will then be at /address/item-name.' => 'Wird aus dem Namen erzeugt, wenn Sie das Feld leer lassen. Die Eintragsseiten liegen dann unter /adresse/name-des-eintrags.',
    'each item has its own page (detail)' => 'Jeder Eintrag hat eine eigene Seite (Detail)',
    'Design the detail page in the builder (Detail template). Without a detail page, items are just cards in the list.' => 'Gestalten Sie die Detailseite im Builder (Detailvorlage). Ohne Detailseite sind die Einträge nur Karten in der Liste.',
    'Item fields' => 'Felder der Einträge',
    'Every item always has a name. Add the fields you need – in the builder you insert them with a {{key}} tag. An empty label removes the field; the key of a saved field never changes.' => 'Jeder Eintrag hat immer einen Namen. Fügen Sie die Felder hinzu, die Sie benötigen – im Builder fügen Sie sie mit einem {{key}}-Tag ein. Eine leere Bezeichnung entfernt das Feld; der Schlüssel eines gespeicherten Feldes ändert sich nie.',
    'created from the label' => 'wird aus der Bezeichnung erzeugt',
    'Save collection' => 'Sammlung speichern',
    'Delete the collection with all its items? Lists on the site will disappear.' => 'Die Sammlung mit allen Einträgen löschen? Die Listen auf der Website verschwinden.',
    'Delete collection' => 'Sammlung löschen',
    'All collections' => 'Alle Sammlungen',
    'The collection is empty.' => 'Die Sammlung ist leer.',
    'Add the first item – then put it on the site with the Collection list element in the builder.' => 'Fügen Sie den ersten Eintrag hinzu – auf die Website bringen Sie ihn dann mit dem Element „Sammlungsliste“ im Builder.',
    'Address, order and visibility' => 'Adresse, Reihenfolge und Sichtbarkeit',
    'Smaller number = earlier in the list.' => 'Kleinere Zahl = weiter oben in der Liste.',
    'published on the site' => 'auf der Website veröffentlicht',
    'Save item' => 'Eintrag speichern',
    'New item' => 'Neuer Eintrag',
    'The collection was saved.' => 'Die Sammlung wurde gespeichert.',
    'The collection and its items were deleted.' => 'Die Sammlung und ihre Einträge wurden gelöscht.',
    'The collection needs a name.' => 'Die Sammlung braucht einen Namen.',
    'The collection does not exist.' => 'Die Sammlung existiert nicht.',
    'The item does not exist.' => 'Der Eintrag existiert nicht.',
    'The item needs a name.' => 'Der Eintrag braucht einen Namen.',
    'The item was saved.' => 'Der Eintrag wurde gespeichert.',
    'The item was deleted.' => 'Der Eintrag wurde gelöscht.',
    'Really delete this item?' => 'Diesen Eintrag wirklich löschen?',
    'The item is saved, but these fields had an invalid value and were left empty: %s' => 'Der Eintrag ist gespeichert, aber diese Felder hatten einen ungültigen Wert und wurden leer gelassen: %s',
    'The address “%s” is already used by the system or another collection.' => 'Die Adresse „%s“ wird bereits vom System oder von einer anderen Sammlung verwendet.',
    'Only the site administrator can change the collection definition and detail template.' => 'Nur der Administrator der Website kann die Definition der Sammlung und die Detailvorlage ändern.',
    'short text' => 'Kurztext',
    'longer text' => 'längerer Text',
    'formatted text' => 'formatierter Text',
    'image' => 'Bild',
    'link' => 'Link',
    'Collection list' => 'Sammlungsliste',
    'pages straight into the builder – edit them visually; the original text stays as a backup' => 'Seiten direkt in den Builder – Sie bearbeiten sie visuell; der ursprüngliche Text bleibt als Backup erhalten',
    'A full-width band with centred content.' => 'Ein Band über die volle Breite mit zentriertem Inhalt.',
    'Content width' => 'Inhaltsbreite',
    'site width' => 'Breite der Website',
    'narrow (text)' => 'schmal (Text)',
    'full width' => 'volle Breite',
    'Container' => 'Container',
    'A group of elements stacked or side by side – a card, a row of buttons.' => 'Eine Gruppe von Elementen untereinander oder nebeneinander – eine Karte, eine Reihe von Buttons.',
    'Whole container as a link (optional)' => 'Ganzer Container als Link (optional)',
    'Grid' => 'Raster',
    'Columns that stack on smaller screens by themselves.' => 'Spalten, die auf kleineren Bildschirmen von selbst untereinander umbrechen.',
    'An H1–H6 heading or a highlighted line.' => 'Eine Überschrift H1–H6 oder eine hervorgehobene Zeile.',
    'Paragraphs, lists, links and tables from the editor.' => 'Absätze, Listen, Links und Tabellen aus dem Editor.',
    'A photo or illustration from Media, optionally with a caption and link.' => 'Ein Foto oder eine Illustration aus den Medien, optional mit Bildunterschrift und Link.',
    'Main image of the page (load immediately)' => 'Hauptbild der Seite (sofort laden)',
    'Call to action: a link shaped as a button.' => 'Handlungsaufforderung: ein Link in Form eines Buttons.',
    'text link' => 'Textlink',
    'Open in a new window' => 'In neuem Fenster öffnen',
    'A list of points – with bullets, numbers or ticks.' => 'Eine Aufzählung von Punkten – mit Aufzählungszeichen, Nummern oder Häkchen.',
