    'redirects changed' => 'Weiterleitungen geändert',
    'page moved to trash' => 'Seite in den Papierkorb verschoben',
    'design system changed' => 'Designsystem geändert',
    'page created' => 'Seite angelegt',
    'page changed' => 'Seite geändert',
    'news item created' => 'News-Beitrag angelegt',
    'news item changed' => 'News-Beitrag geändert',
    'category created' => 'Kategorie angelegt',
    'menu changed' => 'Menü geändert',
    'back to default design' => 'zurück zum Standarddesign',
    'status change' => 'Statusänderung',
    'back to text' => 'zurück zum Text',
    'build published' => 'Builder-Entwurf veröffentlicht',
    'Tokens' => 'Tokens',
    'Article' => 'Artikel',
    'Layers' => 'Ebenen',
    'Send' => 'Senden',
    'Attributes (name=value, one per line; data-…, aria-…, title, lang, role, rel)' => 'Attribute (Name=Wert, pro Zeile; data-…, aria-…, title, lang, role, rel)',
    'Gradient' => 'Farbverlauf',
    'CSS for this element only (property: value;)' => 'CSS nur für dieses Element (Eigenschaft: Wert;)',
    'Search elements or sections' => 'Elemente oder Abschnitte suchen',
    'Search elements or sections…' => 'Elemente oder Abschnitte suchen …',
    'Where it is used' => 'Wo es verwendet wird',
    'My sections' => 'Meine Abschnitte',
    'Mouse hover – also applies to keyboard focus' => 'Maus-Hover – gilt auch für den Tastaturfokus',
    'New class name' => 'Neuer Klassenname',
    'Section name' => 'Name des Abschnitts',
    'Reveal on scroll' => 'Einblenden beim Scrollen',
    'Remove the section “%s” from my sections? It stays on pages where it is already used.' => 'Den Abschnitt „%s“ aus meinen Abschnitten entfernen? Auf Seiten, auf denen er bereits verwendet wird, bleibt er erhalten.',
    'Remove from my sections' => 'Aus meinen Abschnitten entfernen',
    'Used in: ' => 'Verwendet in: ',
    'The section is in the Add panel → My sections.' => 'Der Abschnitt befindet sich im Bereich Hinzufügen → Meine Abschnitte.',
    'The section appears in the Add panel → My sections. Each insert is a separate copy; if it should be the same everywhere, save it as a component.' => 'Der Abschnitt erscheint im Bereich Hinzufügen → Meine Abschnitte. Jedes Einfügen ist eine eigene Kopie; soll er überall gleich sein, speichern Sie ihn als Komponente.',
    'Hide in the editor only (stays on the site)' => 'Nur im Editor ausblenden (auf der Website bleibt er)',
    'Element state' => 'Zustand des Elements',
    'Press' => 'Klick',
    'The class is not used in any published or draft build yet.' => 'Die Klasse wird noch in keinem veröffentlichten oder in Arbeit befindlichen Builder-Entwurf verwendet.',
    'Save to my sections' => 'In meinen Abschnitten speichern',
    'Save to my sections (then insert it on any page)' => 'In meinen Abschnitten speichern (dann fügen Sie ihn auf einer beliebigen Seite ein)',
    'Custom CSS and attributes' => 'Eigenes CSS und Attribute',
    'Outer margin left' => 'Außenabstand links',
    'Outer margin right' => 'Außenabstand rechts',
    'Lock: cannot be selected or moved on the canvas' => 'Sperren: lässt sich auf der Arbeitsfläche weder auswählen noch verschieben',
    'Checking where the class is used…' => 'Es wird geprüft, wo die Klasse verwendet wird …',
    'primary → secondary' => 'Primärfarbe → Sekundärfarbe',
    'soft from the top' => 'sanft von oben',
    'hover and focus' => 'Hover und Fokus',
    'background → surface' => 'Hintergrund → Fläche',
    'press' => 'Klick',
    'slide up' => 'von unten einfahren',
    'darken at the bottom (over a photo)' => 'unten abdunkeln (über einem Foto)',
    'glow in the corner' => 'Leuchten in der Ecke',
    'Nothing like that here.' => 'Nichts Derartiges vorhanden.',
    'The section needs a name.' => 'Der Abschnitt braucht einen Namen.',
    'The element could not be saved.' => 'Das Element konnte nicht gespeichert werden.',
    'Only an administrator can remove sections.' => 'Nur ein Administrator kann Abschnitte entfernen.',
    'section saved to library' => 'Abschnitt in der Bibliothek gespeichert',
    'The copy of the news item is saved as a draft.' => 'Die Kopie des News-Beitrags wurde als Entwurf gespeichert.',
    'The copy of the item is hidden – edit it and publish it.' => 'Die Kopie des Eintrags ist verborgen – bearbeiten und veröffentlichen Sie sie.',
    'Roles' => 'Rollen',
    'Edit role' => 'Rolle bearbeiten',
    'New role' => 'Neue Rolle',
    'The role does not exist.' => 'Die Rolle existiert nicht.',
    'Fill in the role name.' => 'Füllen Sie den Namen der Rolle aus.',
    'A role with this name already exists.' => 'Eine Rolle mit diesem Namen existiert bereits.',
    'Select at least one section.' => 'Wählen Sie mindestens einen Bereich aus.',
    'The role has been saved.' => 'Die Rolle wurde gespeichert.',
    'The role has been deleted. Its members kept their current access.' => 'Die Rolle wurde gelöscht. Ihre Mitglieder behalten ihren bisherigen Zugriff.',
    'Writes own content' => 'Schreibt eigene Inhalte',
    'Only own news and without publishing – an editor publishes.' => 'Nur eigene News und ohne Veröffentlichung – ein Redakteur veröffentlicht.',
    'Manages everyone\'s content' => 'Verwaltet die Inhalte aller',
    'Edits and publishes news by all authors.' => 'Bearbeitet und veröffentlicht News aller Autoren.',
    'Back to users' => 'Zurück zu den Benutzern',
    'The built-in roles News author, Editor and Administrator are enough for most websites. A custom role is useful when someone should see only part of the administration – for example a salesperson only Enquiries.' => 'Die integrierten Rollen News-Autor, Redakteur und Administrator genügen den meisten Websites. Eine eigene Rolle ist nützlich, wenn jemand nur einen Teil der Administration sehen soll – zum Beispiel ein Vertriebsmitarbeiter nur die Anfragen.',
    'No custom roles yet.' => 'Noch keine eigenen Rollen.',
    'Delete the role? Its members will keep their current access.' => 'Die Rolle löschen? Ihre Mitglieder behalten ihren bisherigen Zugriff.',
    'Back to roles' => 'Zurück zu den Rollen',
    'Role name' => 'Name der Rolle',
    'e.g. Salesperson' => 'z. B. Vertriebsmitarbeiter',
    'Website settings, users and appearance stay with the administrator.' => 'Einstellungen der Website, Benutzer und Erscheinungsbild bleiben beim Administrator.',
    'Saving also changes the permissions of these users:' => 'Das Speichern ändert auch die Berechtigungen dieser Benutzer:',
    'Custom role' => 'Eigene Rolle',
    'a named set of sections, for example only Enquiries for a salesperson.' => 'ein benannter Satz von Bereichen, zum Beispiel nur die Anfragen für einen Vertriebsmitarbeiter.',
    'An author usually has only News, an editor all content sections, an administrator everything. With a custom role, the role\'s sections apply.' => 'Ein Autor hat üblicherweise nur News, ein Redakteur alle Inhaltsbereiche, ein Administrator alles. Bei einer eigenen Rolle gelten die Bereiche der Rolle.',
    'Tap the place on the page to move the element to (top or bottom part of an element = before or after, middle of a container = inside). Esc cancels.' => 'Tippen Sie auf die Stelle auf der Seite, an die das Element verschoben werden soll (oberer oder unterer Teil eines Elements = davor oder dahinter, Mitte eines Containers = hinein). Esc bricht ab.',
    'Drag or tap to move' => 'Zum Verschieben ziehen oder tippen',
    'Move by tapping the target (works on touch screens too)' => 'Durch Tippen auf das Ziel verschieben (auch auf Touchscreens)',
    'Compose your own' => 'Eigenen zusammenstellen',
