    'Type area names into the cells (the same name across several cells = the element spans them). Then give the nested element its “Grid area”.' => 'Tragen Sie Namen der Bereiche in die Zellen ein (derselbe Name über mehrere Zellen = das Element erstreckt sich darüber). Geben Sie dem verschachtelten Element dann seinen „Rasterbereich“.',
