    'least used' => 'am wenigsten verwendet',
    'Search name, description or file' => 'Name, Beschreibung oder Datei suchen',
    'Search media' => 'In den Medien suchen',
    'Description of image %s' => 'Beschreibung des Bildes %s',
    'You cannot edit this image.' => 'Sie können dieses Bild nicht bearbeiten.',
    'Design tokens (Figma, Tokens Studio)' => 'Design-Tokens (Figma, Tokens Studio)',
    'Colours, fonts, sizes and typography styles in the W3C Design Tokens format (DTCG). A Kaleta export can be loaded back in full; from another tool the colours are taken.' => 'Farben, Schriften, Größen und Typografiestile im W3C-Design-Tokens-Format (DTCG). Ein Kaleta-Export lässt sich vollständig wieder laden; aus einem anderen Werkzeug werden die Farben übernommen.',
    'Download tokens (.tokens.json)' => 'Tokens herunterladen (.tokens.json)',
    'Load tokens? They will overwrite the appearance settings above.' => 'Tokens laden? Sie überschreiben die Einstellungen des Erscheinungsbilds oben.',
    'Tokens file' => 'Tokens-Datei',
    'Load tokens' => 'Tokens laden',
    'The file contains no usable design tokens (a JSON file in the DTCG format is expected).' => 'Die Datei enthält keine verwendbaren Design-Tokens (erwartet wird eine JSON-Datei im DTCG-Format).',
    'Design tokens have been loaded.' => 'Die Design-Tokens wurden geladen.',
    'The enquiry form collects personal data – visitors must know how you handle it. The page is prepared as a hidden draft: fill in the details in square brackets and publish it.' => 'Das Anfrageformular erfasst personenbezogene Daten – Besucher müssen wissen, wie Sie damit umgehen. Die Seite ist als verborgener Entwurf vorbereitet: Ergänzen Sie die Angaben in eckigen Klammern und veröffentlichen Sie sie.',
    'Always-on core: Pages, Collections, Media, Site appearance, Site parts, Menu, Components, Pop-ups, Users and roles, Import and export, Change log and Settings.' => 'Stets aktiver Kern: Seiten, Sammlungen, Medien, Erscheinungsbild der Website, Seitenbereiche, Menü, Komponenten, Pop-ups, Benutzer und Rollen, Import und Export, Änderungsprotokoll und Einstellungen.',
    'In the Claude app you do not need a token: add a custom connector with the address %s and confirm access by signing in.' => 'In der Claude-App benötigen Sie keinen Token: Fügen Sie einen benutzerdefinierten Connector mit der Adresse %s hinzu und bestätigen Sie den Zugriff durch Anmeldung.',
    'Enquiries and retention' => 'Anfragen und Aufbewahrungsdauer',
    'Webhook to CRM' => 'Webhook zum CRM',
    'Subscribers and export' => 'Abonnenten und Export',
    'Choose languages' => 'Sprachen auswählen',
    'Provider, key and model' => 'Anbieter, Schlüssel und Modell',
    'How to connect Claude' => 'So verbinden Sie Claude',
    'Links for an extension appear once it is switched on and saved.' => 'Links zu einer Erweiterung erscheinen, sobald sie aktiviert und gespeichert ist.',
    'Claude connection – how to connect' => 'Claude-Anbindung – so verbinden Sie',
    'In the Claude app open Settings → Connectors → Add custom connector.' => 'Öffnen Sie in der Claude-App Einstellungen → Connectors → Benutzerdefinierten Connector hinzufügen.',
    'Enter this address:' => 'Geben Sie diese Adresse ein:',
    'Claude sends you here to sign in and confirm access. It then works with your account\'s permissions – builds and news are saved as drafts.' => 'Claude schickt Sie hierher, damit Sie sich anmelden und den Zugriff bestätigen. Danach arbeitet es mit den Rechten Ihres Kontos – im Builder erstellte Seiten und News werden als Entwürfe gespeichert.',
    'In Claude Code, just run:' => 'In Claude Code genügt der Befehl:',
    'Connected applications and personal tokens for other tools are in' => 'Verbundene Anwendungen und persönliche Tokens für andere Werkzeuge finden Sie unter',
    'The connector needs the site on HTTPS in the domain root.' => 'Der Connector benötigt die Website über HTTPS im Stammverzeichnis der Domain.',
    'Administrator' => 'Administrator',
    'Published pages' => 'Veröffentlichte Seiten',
    'Pages with unpublished changes' => 'Seiten mit nicht veröffentlichten Änderungen',
    'Published news' => 'Veröffentlichte News',
    'News drafts' => 'News-Entwürfe',
    'Logo, main colour and fonts.' => 'Logo, Primärfarbe und Schriften.',
    'Prepare your pages' => 'Bereiten Sie Ihre Seiten vor',
    'About us, Services, Contact – and pick the home page in Settings.' => 'Über uns, Leistungen, Kontakt – und wählen Sie in den Einstellungen die Startseite aus.',
    'Complete the privacy policy' => 'Datenschutzerklärung vervollständigen',
    'Set up e-mail' => 'E-Mail einrichten',
    'Where the site sends e-mail from (forms, password reset).' => 'Von wo die Website E-Mails versendet (Formulare, Passwort zurücksetzen).',
    'Business' => 'Geschäftlich',
    'Blue, sans-serif type, modest rounding' => 'Blau, serifenlose Schrift, dezente Rundungen',
    'Warm earthy colours, serif headings' => 'Warme Erdtöne, Überschriften mit Serifen',
    'Friendly' => 'Freundlich',
    'Fresh green, rounded type and corners' => 'Frisches Grün, abgerundete Schrift und Ecken',
    'Elegant' => 'Elegant',
    'Dark tones, large serif headings, sharp edges' => 'Dunkle Töne, große Überschriften mit Serifen, scharfe Kanten',
    'Technology' => 'Technologie',
    'Purple, bold grotesque, high contrast' => 'Violett, kräftige Grotesk, hoher Kontrast',
    'Primary' => 'Primär',
    'Primary – soft' => 'Primär – sanft',
    'Text on primary' => 'Text auf Primärfarbe',
    'Secondary' => 'Sekundär',
    'Surface (cards, footer)' => 'Fläche (Karten, Fußbereich)',
    'Surface' => 'Fläche',
    'Muted text' => 'Gedämpfter Text',
    'White' => 'Weiß',
    'Black' => 'Schwarz',
    'Text on background' => 'Text auf Hintergrund',
    'Text on surface' => 'Text auf Fläche',
    'Link (primary colour) on background' => 'Link (Primärfarbe) auf Hintergrund',
    'Button text on primary colour' => 'Buttontext auf Primärfarbe',
    'Secondary colour on background' => 'Sekundärfarbe auf Hintergrund',
    'subtle (1.125)' => 'dezent (1,125)',
    'calm (1.2)' => 'ruhig (1,2)',
    'balanced (1.25)' => 'ausgewogen (1,25)',
    'strong (1.333)' => 'kräftig (1,333)',
    'dramatic (1.414)' => 'dramatisch (1,414)',
    'poster (1.5)' => 'Plakat (1,5)',
    'A wrapper around the news item – a call to action or more news below the text, for example.' => 'Ein Rahmen um den News-Beitrag – zum Beispiel eine Handlungsaufforderung oder weitere News unter dem Text.',
    'Writes and edits their own news. An editor publishes them.' => 'Schreibt und bearbeitet eigene News. Ein Redakteur veröffentlicht sie.',
    'Manages all site content – pages, news, media – and publishes.' => 'Verwaltet alle Inhalte der Website – Seiten, News, Medien – und veröffentlicht.',
    '301 redirects from old addresses – essential after moving from another site.' => '301-Weiterleitungen von alten Adressen – unverzichtbar nach dem Umzug von einer anderen Website.',
    'A site in several languages: each further version (e.g. /cs/…) has its own pages, categories and news, a language switcher and hreflang tags. Pick the languages in Settings → General.' => 'Eine Website in mehreren Sprachen: Jede weitere Version (z. B. /en/…) hat eigene Seiten, Kategorien und News, einen Sprachumschalter und hreflang-Tags. Die Sprachen wählen Sie unter Einstellungen → Allgemein.',
    'An address from Make, Zapier, IFTTT or n8n. When a news item is published, the system sends it the title, lead, address and image – the service then shares it on Facebook, X, Mastodon, Slack and so on.' => 'Eine Adresse von Make, Zapier, IFTTT oder n8n. Nach der Veröffentlichung eines News-Beitrags sendet das System ihr Titel, Teaser, Adresse und Bild – der Dienst teilt sie dann auf Facebook, X, Mastodon, Slack usw.',
    'Recommended. Applies only to releases marked as security releases; you install regular versions yourself. The system checks for updates twice a day, backs up the database before installing and e-mails the result to the site e-mail.' => 'Empfohlen. Betrifft nur Veröffentlichungen, die als Sicherheitsupdates gekennzeichnet sind; reguläre Versionen installieren Sie selbst. Das System prüft zweimal täglich auf Updates, sichert vor der Installation die Datenbank und sendet das Ergebnis per E-Mail an die Website-E-Mail.',
    'Finished pages are served to visitors from memory – the site is faster and copes with traffic peaks. Leave it on.' => 'Fertige Seiten werden den Besuchern aus dem Speicher ausgeliefert – die Website ist schneller und verkraftet Lastspitzen. Lassen Sie es aktiviert.',
    'Every news item also as plain text without navigation – for language models and AI search engines.' => 'Jeder News-Beitrag auch als reiner Text ohne Navigation – für Sprachmodelle und KI-Suchmaschinen.',
    'In the background, one news item every five minutes. The result is in News → Broken links.' => 'Im Hintergrund, ein News-Beitrag alle fünf Minuten. Das Ergebnis finden Sie unter News → Defekte Links.',
    'For example https://www.example.com, without a trailing slash. Links in e-mails, RSS, the sitemap and notifications are built from it. Change it after moving to another domain.' => 'Zum Beispiel https://www.example.com, ohne Schrägstrich am Ende. Daraus werden Links in E-Mails, RSS, der Sitemap und Benachrichtigungen gebildet. Ändern Sie sie nach dem Umzug auf eine andere Domain.',
    'For example the registered company name and company ID.' => 'Zum Beispiel Firmenname laut Handelsregister und USt-IdNr.',
    'News items per page' => 'News-Beiträge pro Seite',
    'Visitors see only the notice below. Signed-in users see the site as usual.' => 'Besucher sehen nur den Hinweis unten. Angemeldete Benutzer sehen die Website wie gewohnt.',
    'Visits, most-read news and traffic sources under Statistics. No cookies and no consent needed.' => 'Besuche, meistgelesene News und Besucherquellen im Bereich Statistik. Ohne Cookies und ohne Einwilligung.',
    'News table of contents from subheadings' => 'Inhaltsverzeichnis des News-Beitrags aus Zwischenüberschriften',
    'Share links below the news item' => 'Links zum Teilen unter dem News-Beitrag',
    'Notify search engines about new news (IndexNow)' => 'Suchmaschinen über neue News informieren (IndexNow)',
    'Similar news by tags and category is offered below a news item.' => 'Unter einem News-Beitrag werden ähnliche News nach Schlagwörtern und Kategorie angeboten.',
    'Empty = the site e-mail. With SMTP it must be an address your mailbox is allowed to send from.' => 'Leer = die Website-E-Mail. Bei SMTP muss es eine Adresse sein, von der Ihr Postfach senden darf.',
    'Related news' => 'Verwandte News',
    'News items with at least three subheadings get a clickable outline above the text.' => 'News-Beiträge mit mindestens drei Zwischenüberschriften erhalten über dem Text eine anklickbare Gliederung.',
    'Webhook after publishing news' => 'Webhook nach der Veröffentlichung eines News-Beitrags',
    'Plain-text news (.md)' => 'News als reiner Text (.md)',
    'Bodoni, Didot – elegance and fashion' => 'Bodoni, Didot – Eleganz und Mode',
    'Helvetica, Arial – strong and confident' => 'Helvetica, Arial – kraftvoll und selbstbewusst',
    'friendly, for services and family businesses' => 'freundlich, für Dienstleistungen und Familienbetriebe',
    'technology and development' => 'Technologie und Entwicklung',
    'write and edit pages and news, and manage categories, collections and the look of the site.' => 'Seiten und News schreiben und bearbeiten sowie Kategorien, Sammlungen und das Erscheinungsbild der Website verwalten.',
    'write and edit news.' => 'News schreiben und bearbeiten.',
    'no icon' => 'kein Icon',
    'Icon left of the text' => 'Icon links vom Text',
    'Current item highlight' => 'Hervorhebung des aktuellen Eintrags',
    'underline in the secondary colour' => 'Unterstreichung in der Sekundärfarbe',
    'Site email' => 'Website-E-Mail',
    'Public email' => 'Öffentliche E-Mail',
    'With country code, e.g. +420 123 456 789.' => 'Mit Ländervorwahl, z. B. +49 123 456789.',
    'Contact for visitors and search engines. The site email from the General tab (where enquiries are sent) is not shown on the site.' => 'Kontakt für Besucher und Suchmaschinen. Die Website-E-Mail aus dem Tab „Allgemein“ (an sie werden Anfragen gesendet) wird auf der Website nicht angezeigt.',
    'Keep consent records (months)' => 'Einwilligungsprotokolle aufbewahren (Monate)',
    'Older records are deleted automatically. 0 = keep.' => 'Ältere Einträge werden automatisch gelöscht. 0 = behalten.',
    'Headings on phones' => 'Überschriften auf Smartphones',
    'Headings on monitors' => 'Überschriften auf Monitoren',
    'News author' => 'News-Autor',
    'builder' => 'Builder',
    'News item saved. It will appear on the site once an editor publishes it.' => 'News-Beitrag gespeichert. Er erscheint auf der Website, sobald ein Redakteur ihn veröffentlicht.',
    '%s:1' => '%s:1',
    'Account and tools' => 'Konto und Werkzeuge',
    'News items need a category, so the category “%s” has been created. You can rename it or add more under News → Categories.' => 'News-Beiträge benötigen eine Kategorie, daher wurde die Kategorie „%s“ angelegt. Sie können sie umbenennen oder weitere unter News → Kategorien hinzufügen.',
    'The file is larger than the server allows (%s at most). Make it smaller or ask your hosting provider to raise the limit.' => 'Die Datei ist größer, als der Server erlaubt (höchstens %s). Verkleinern Sie sie oder bitten Sie Ihren Hosting-Anbieter, das Limit zu erhöhen.',
    'Awaiting publication' => 'Warten auf Veröffentlichung',
    'awaiting publication' => 'wartet auf Veröffentlichung',
    'News authors cannot publish – review this news item and publish it.' => 'News-Autoren können nicht veröffentlichen – prüfen Sie diesen News-Beitrag und veröffentlichen Sie ihn.',
    'News from authors awaiting publication' => 'News von Autoren warten auf Veröffentlichung',
    'In your authenticator app (Google Authenticator, Microsoft Authenticator, 1Password, Aegis…) add a new account by scanning the QR code:' => 'Fügen Sie in Ihrer Authenticator-App (Google Authenticator, Microsoft Authenticator, 1Password, Aegis …) ein neues Konto hinzu, indem Sie den QR-Code scannen:',
    'QR code for the authenticator app' => 'QR-Code für die Authenticator-App',
    'Cannot scan it? Add the account by typing the key:' => 'Scannen funktioniert nicht? Fügen Sie das Konto durch Eingabe des Schlüssels hinzu:',
    'page “%s”' => 'Seite „%s“',
    'collection detail “%s”' => 'Sammlungsdetail „%s“',
    'component “%s”' => 'Komponente „%s“',
    'The component “%s” is used on: %s. Deleting it leaves an empty space there. Delete it anyway?' => 'Die Komponente „%s“ wird verwendet auf: %s. Beim Löschen bleibt dort eine leere Stelle. Trotzdem löschen?',
    'and %d more' => 'und %d weitere',
    'Add a description for blind visitors (alt text) to the images: what the image shows.' => 'Ergänzen Sie bei den Bildern eine Beschreibung für blinde Besucher (Alt-Text): was auf dem Bild zu sehen ist.',
    'The database update failed: %s. The site keeps running; install the fix in Settings → Backups and updates, or write to info@kaletacms.com.' => 'Das Datenbank-Update ist fehlgeschlagen: %s. Die Website läuft weiter; installieren Sie die Korrektur unter Einstellungen → Backups und Updates oder schreiben Sie an info@kaletacms.com.',
    'Border colour' => 'Rahmenfarbe',
    'preview shared' => 'Vorschau geteilt',
    'Kaleta is free and has no ads.' => 'Kaleta ist kostenlos und werbefrei.',
    'Support its development on GitHub Sponsors' => 'Unterstützen Sie die Entwicklung auf GitHub Sponsors',
    'Imprint (all details of the operator)' => 'Impressum (alle Angaben zum Betreiber)',
    'Imprint (legal notice)' => 'Impressum (Anbieterkennzeichnung)',
    'Company identification number; in other countries its registration number.' => 'Identifikationsnummer des Unternehmens; in anderen Ländern dessen Registernummer.',
    'Register court and entry, e.g. “Amtsgericht München, HRB 12345” or “Companies House, 01234567”. For the imprint.' => 'Registergericht und Eintrag, z. B. „Amtsgericht München, HRB 12345“ oder „Companies House, 01234567“. Für das Impressum.',
    'Who represents the company, e.g. “Managing director: Jane Smith” (Geschäftsführer). For the imprint.' => 'Wer das Unternehmen vertritt, z. B. „Geschäftsführerin: Erika Mustermann“. Für das Impressum.',
    'Texts for visitors (Search, Read more…) are translated into: %s. Other languages show them in English, with dates in their own format. You write the content of pages and news in the language of the version.' => 'Texte für Besucher (Suchen, Weiterlesen …) sind übersetzt in: %s. Andere Sprachen zeigen sie auf Englisch an, mit Datumsangaben im eigenen Format. Die Inhalte von Seiten und News schreiben Sie in der Sprache der jeweiligen Version.',
    '%s: %s visits' => '%s: %s Besuche',
    'always dark' => 'immer dunkel',
    'Switcher for visitors – in the header they choose light, dark or matching their device (the choice is remembered in their browser)' => 'Umschalter für Besucher – im Kopfbereich wählen sie hell, dunkel oder passend zu ihrem Gerät (die Auswahl wird in ihrem Browser gespeichert)',
    'Only items with the value (on an item page also {{field}} – related content)' => 'Nur Einträge mit dem Wert (auf einer Eintragsseite auch {{field}} – verwandte Inhalte)',
    'Leave out the item being shown (related content on an item page)' => 'Den angezeigten Eintrag auslassen (verwandte Inhalte auf einer Eintragsseite)',
    'Another window already uses the address “%s”.' => 'Ein anderes Pop-up verwendet die Adresse „%s“ bereits.',
    'Pop-ups' => 'Pop-ups',
    'The pop-up does not exist.' => 'Das Pop-up existiert nicht.',
    'The pop-up needs a name.' => 'Das Pop-up braucht einen Namen.',
    'The pop-up settings were saved.' => 'Die Einstellungen des Pop-ups wurden gespeichert.',
    'Publish the pop-up in the builder first – then you can turn it on.' => 'Veröffentlichen Sie das Pop-up zuerst im Builder – erst dann können Sie es aktivieren.',
    'The pop-up counters were reset.' => 'Die Zähler des Pop-ups wurden zurückgesetzt.',
    'The pop-up was deleted.' => 'Das Pop-up wurde gelöscht.',
    'The pop-up is off – it no longer shows on the site.' => 'Das Pop-up ist deaktiviert – es wird auf der Website nicht mehr angezeigt.',
    'The pop-up is on and shows on the site according to its rules.' => 'Das Pop-up ist aktiviert und wird gemäß seinen Regeln auf der Website angezeigt.',
    'New pop-up' => 'Neues Pop-up',
    'No pop-ups yet.' => 'Noch keine Pop-ups.',
    'A window over the page for a newsletter sign-up, a download, an announcement or an offer. You build the content in the builder and set when and where it shows. The counters work without cookies.' => 'Ein Fenster über der Seite für die Newsletter-Anmeldung, einen Download, eine Ankündigung oder ein Angebot. Den Inhalt erstellen Sie im Builder, in den Einstellungen legen Sie fest, wann und wo es angezeigt wird. Die Zähler funktionieren ohne Cookies.',
    'Create a pop-up' => 'Pop-up anlegen',
    'Pop-up' => 'Pop-up',
    'When it shows' => 'Wann es angezeigt wird',
    'Views' => 'Anzeigen',
    'Closes' => 'Schließungen',
    'Language switcher' => 'Sprachumschalter',
    'Choose the language version of the site – a row of codes or a dropdown (for example in the footer).' => 'Auswahl der Sprachversion der Website – eine Reihe von Kürzeln oder ein Dropdown (zum Beispiel im Fußbereich).',
    'dropdown' => 'Dropdown',
    'codes in a row' => 'Kürzel in einer Reihe',
    'The dropdown opens' => 'Das Dropdown öffnet sich',
    'upwards (footer)' => 'nach oben (Fußbereich)',
    'downwards (header)' => 'nach unten (Kopfbereich)',
    'Language switcher (turn it off when it is elsewhere, for example in the footer)' => 'Sprachumschalter (deaktivieren, wenn er an anderer Stelle ist, zum Beispiel im Fußbereich)',
    'All pop-ups' => 'Alle Pop-ups',
    'Conversions' => 'Conversions',
    'on the whole site' => 'auf der gesamten Website',
    'in selected places' => 'an ausgewählten Stellen',
    'A conversion is a form sent or a newsletter sign-up in the pop-up. The counters work without cookies and without any visitor data.' => 'Eine Conversion ist ein abgesendetes Formular oder eine Newsletter-Anmeldung im Pop-up. Die Zähler funktionieren ohne Cookies und ohne Besucherdaten.',
    'Pop-up name' => 'Name des Pop-ups',
    'e.g. Newsletter on the blog' => 'z. B. Newsletter im Blog',
    'Only for you in the admin and for screen readers. The address #popup-… is made from the name.' => 'Nur für Sie in der Administration und für Screenreader. Aus dem Namen wird die Adresse #popup-… gebildet.',
    'Start from' => 'Beginnen mit',
    'The pop-up is created turned off and opens in the builder. It shows on the site once you publish it and turn it on.' => 'Das Pop-up wird deaktiviert angelegt und öffnet sich im Builder. Auf der Website wird es angezeigt, sobald Sie es veröffentlichen und aktivieren.',
    'Edit the content in the builder' => 'Inhalt im Builder bearbeiten',
    'A link or button to #popup-%s opens the pop-up at any time – even when it does not show on its own.' => 'Ein Link oder Button mit der Adresse #popup-%s öffnet das Pop-up jederzeit – auch wenn es nicht von selbst angezeigt wird.',
    'When the pop-up shows' => 'Wann das Pop-up angezeigt wird',
    'Trigger' => 'Auslöser',
    'Trigger value' => 'Wert des Auslösers',
    'Seconds for time and idle, percent of the page for scrolling, number of pages for the visit.' => 'Sekunden bei Zeit und Inaktivität, Prozent der Seite beim Scrollen, Anzahl der Seiten beim Besuch.',
    'Frequency' => 'Häufigkeit',
    'number of days' => 'Anzahl Tage',
    'The visitor’s browser remembers it (sessionStorage and localStorage), not cookies.' => 'Der Browser des Besuchers merkt es sich (sessionStorage und localStorage), nicht Cookies.',
    'Where the pop-up shows' => 'Wo das Pop-up angezeigt wird',
    'Places' => 'Orte',
    'only on selected pages, in collections or in news' => 'nur auf ausgewählten Seiten, in Sammlungen oder bei News',
    'Collection item pages' => 'Eintragsseiten von Sammlungen',
    'the news list, categories and news items' => 'die News-Liste, Kategorien und einzelne News-Beiträge',
    'from' => 'von',
    'to' => 'bis',
    'Empty = no limit. Outside the period the pop-up is not added to the page at all.' => 'Leer = keine Begrenzung. Außerhalb des Zeitraums wird das Pop-up gar nicht in die Seite eingefügt.',
    'Only from a campaign' => 'Nur aus einer Kampagne',
    'Text in the utm_* parameters of the address the visitor arrived with (e.g. spring or newsletter). Empty = everyone.' => 'Text in den utm_*-Parametern der Adresse, mit der der Besucher gekommen ist (z. B. spring oder newsletter). Leer = alle.',
    'Only from a referrer' => 'Nur von einer verweisenden Seite',
    'Part of the address of the site the visitor came from (e.g. facebook.com). Empty = from anywhere.' => 'Teil der Adresse der Website, von der der Besucher kam (z. B. facebook.com). Leer = von überall.',
    'When several pop-ups would show, the lower number goes first. No pop-up opens over an open one.' => 'Wenn mehrere Pop-ups erscheinen würden, kommt die niedrigere Zahl zuerst. Über einem geöffneten Pop-up öffnet sich kein weiteres.',
    'Reset the counters of views, closes and conversions?' => 'Die Zähler für Aufrufe, Schließungen und Conversions zurücksetzen?',
