    'Username: 2–40 characters, letters without accents, digits, dot, hyphen, underscore.' => 'Benutzername: 2–40 Zeichen, Buchstaben ohne Akzente, Ziffern, Punkt, Bindestrich, Unterstrich.',
    'Could not connect to the database:' => 'Verbindung zur Datenbank nicht möglich:',
    'Tables with this prefix already exist in the database. Choose another prefix or remove them first.' => 'In der Datenbank existieren bereits Tabellen mit diesem Präfix. Wählen Sie ein anderes Präfix oder entfernen Sie die Tabellen zuerst.',
    'Creating the tables failed:' => 'Das Erstellen der Tabellen ist fehlgeschlagen:',
    'The tables were created, but config.php could not be written. Check the write permissions.' => 'Die Tabellen wurden erstellt, aber config.php konnte nicht geschrieben werden. Prüfen Sie die Schreibrechte.',
    'Start with a website' => 'Mit einer Website starten',
