    'Text rewritten – Ctrl+Z undoes it.' => 'Text umgeschrieben – Ctrl+Z macht es rückgängig.',
    'Your session has expired. Sign in again in a new tab – your unsaved changes stay here and will save automatically.' => 'Ihre Sitzung ist abgelaufen. Melden Sie sich in einem neuen Tab erneut an – Ihre nicht gespeicherten Änderungen bleiben hier erhalten und werden automatisch gespeichert.',
