    '…or find a news item on the site' => '…oder einen News-Beitrag auf der Website finden',
    'Image description for blind visitors' => 'Bildbeschreibung für blinde Besucher',
    'Image without a description – neither a blind visitor nor a search engine knows what it shows. Add a description and confirm with Enter:' => 'Bild ohne Beschreibung – weder ein blinder Besucher noch eine Suchmaschine weiß, was es zeigt. Fügen Sie eine Beschreibung hinzu und bestätigen Sie mit Enter:',
    ' above it). Screen readers build the outline of the text from the levels.' => ' darüber). Screenreader erstellen die Gliederung des Textes anhand der Ebenen.',
    'The intro is missing – the news list and social sharing need it.' => 'Die Einleitung fehlt – die News-Liste und das Teilen in sozialen Netzwerken benötigen sie.',
    'The suggestion is only inserted into the field – you can keep editing it. Nothing is saved until you save the form.' => 'Der Vorschlag wird nur in das Feld eingefügt – Sie können ihn weiter bearbeiten. Nichts wird gespeichert, bevor Sie das Formular speichern.',
