    'Cancel scheduling' => 'Planung abbrechen',
    'Sending to subscribers needs the publishing permission – ask an editor or an administrator.' => 'Zum Senden an Abonnenten ist die Berechtigung zum Veröffentlichen erforderlich – fragen Sie einen Redakteur oder Administrator.',
    'Send the newsletter to %d confirmed subscribers? Save your changes first – the saved version goes out.' => 'Den Newsletter an %d bestätigte Abonnenten senden? Speichern Sie zuerst Ihre Änderungen – die gespeicherte Version wird versendet.',
    'now' => 'jetzt',
    'at' => 'am',
    'Date and time of sending' => 'Datum und Uhrzeit des Versands',
    'Send to %d subscribers' => 'An %d Abonnenten senden',
    'The newsletter needs a subject.' => 'Der Newsletter benötigt einen Betreff.',
    'Choose at least one news item, or send the latest news.' => 'Wählen Sie mindestens einen News-Beitrag aus oder senden Sie die neuesten News.',
    'The button link must be an https:// address or a path on the site starting with /.' => 'Der Button-Link muss eine https://-Adresse oder ein Pfad auf der Website sein, der mit / beginnt.',
    'The newsletter does not exist.' => 'Der Newsletter existiert nicht.',
    'A newsletter that is being sent or was sent cannot be changed.' => 'Ein Newsletter, der gerade gesendet wird oder bereits gesendet wurde, kann nicht geändert werden.',
    'The newsletter is being sent right now – it cannot be deleted until it finishes.' => 'Der Newsletter wird gerade gesendet – er kann erst nach Abschluss gelöscht werden.',
    'The newsletter has already been sent.' => 'Der Newsletter wurde bereits gesendet.',
    'There are no confirmed subscribers yet.' => 'Es gibt noch keine bestätigten Abonnenten.',
    'The newsletter has no news items to send – publish a news item or choose No news.' => 'Der Newsletter hat keine News-Beiträge zum Senden – veröffentlichen Sie einen News-Beitrag oder wählen Sie „Keine News“.',
    'The time must be in the future, as YYYY-MM-DD HH:MM.' => 'Die Zeit muss in der Zukunft liegen, im Format JJJJ-MM-TT HH:MM.',
    'The test address is not a valid e-mail.' => 'Die Testadresse ist keine gültige E-Mail-Adresse.',
    'Newsletters are sent only through an SMTP server (Brevo, Amazon SES, Mailgun, your mailbox…) – set it up in Settings → Mail.' => 'Newsletter werden nur über einen SMTP-Server versendet (Brevo, Amazon SES, Mailgun, Ihr Postfach …) – richten Sie ihn unter Einstellungen → E-Mail ein.',
    'Cron has not called the tasks address in the last 30 minutes – newsletters go out in batches only while it runs. Set it up with the address in Settings → System status.' => 'Cron hat die Aufgabenadresse in den letzten 30 Minuten nicht aufgerufen – Newsletter gehen nur in Paketen hinaus, solange es läuft. Richten Sie es mit der Adresse unter Einstellungen → Zustand ein.',
    'The newsletter was saved.' => 'Der Newsletter wurde gespeichert.',
    'Sending to subscribers needs the publishing permission.' => 'Zum Senden an Abonnenten ist die Berechtigung zum Veröffentlichen erforderlich.',
    'The newsletter is scheduled for %s.' => 'Der Newsletter ist für %s geplant.',
    'Sending has started: %d subscribers. The e-mails go out in batches each time cron runs.' => 'Der Versand hat begonnen: %d Abonnenten. Die E-Mails gehen bei jedem Cron-Lauf in Paketen hinaus.',
    'Scheduling was cancelled – the newsletter is a draft again.' => 'Die Planung wurde abgebrochen – der Newsletter ist wieder ein Entwurf.',
    'The newsletter was deleted.' => 'Der Newsletter wurde gelöscht.',
    'Your account has no e-mail address – add one under My account.' => 'Ihr Konto hat keine E-Mail-Adresse – fügen Sie unter „Mein Konto“ eine hinzu.',
    'The test e-mail went to %s.' => 'Die Test-E-Mail wurde an %s gesendet.',
    'The test e-mail could not be sent: %s' => 'Die Test-E-Mail konnte nicht gesendet werden: %s',
    'Cron' => 'Cron',
    'not set up – scheduled work waits for visits, and newsletters cannot be sent; you will find the address further down this page' => 'nicht eingerichtet – geplante Aufgaben warten auf Besuche, und Newsletter können nicht gesendet werden; die Adresse finden Sie weiter unten auf dieser Seite',
    'last run %s – newsletters are not being sent until cron runs again' => 'letzter Lauf %s – Newsletter werden erst wieder gesendet, wenn Cron erneut läuft',
    'Newsletters: e-mails per hour' => 'Newsletter: E-Mails pro Stunde',
    'Newsletters go out in batches while cron runs. Keep to the sending limit of your SMTP service – free plans often allow only a few hundred e-mails a day.' => 'Newsletter gehen in Paketen hinaus, solange Cron läuft. Halten Sie das Versandlimit Ihres SMTP-Dienstes ein – kostenlose Tarife erlauben oft nur einige hundert E-Mails pro Tag.',
    'Test' => 'Test',
    'Deleted items stay here for 30 days, then they are deleted permanently.' => 'Gelöschte Einträge bleiben hier 30 Tage lang erhalten und werden dann endgültig gelöscht.',
    'Back to items' => 'Zurück zu den Einträgen',
    'Items in the trash are not on the site. A restored item comes back hidden; after 30 days it is permanently deleted from the trash.' => 'Einträge im Papierkorb sind nicht auf der Website. Ein wiederhergestellter Eintrag kommt verborgen zurück; nach 30 Tagen wird er endgültig aus dem Papierkorb gelöscht.',
    'Delete the item permanently? This cannot be undone.' => 'Den Eintrag endgültig löschen? Das lässt sich nicht rückgängig machen.',
    'Move the item to the trash? It disappears from the site; you can restore it for 30 days.' => 'Den Eintrag in den Papierkorb verschieben? Er verschwindet von der Website; Sie können ihn 30 Tage lang wiederherstellen.',
    'The item is in the trash – it is no longer on the site; you can restore it for 30 days.' => 'Der Eintrag liegt im Papierkorb – er ist nicht mehr auf der Website; Sie können ihn 30 Tage lang wiederherstellen.',
    'The item was restored as hidden.' => 'Der Eintrag wurde als verborgen wiederhergestellt.',
    'The item was deleted permanently.' => 'Der Eintrag wurde endgültig gelöscht.',
    '%d enquiries read' => '%d Anfragen gelesen',
    'Custom layout' => 'Eigenes Layout',
    '%s in the layout/ folder is no longer used – since 1.6 the look comes only from Site appearance and the builder. Move what you need into shared classes and site parts, then delete the folder.' => '%s im Ordner layout/ wird nicht mehr verwendet – seit 1.6 stammt das Erscheinungsbild nur noch aus dem Erscheinungsbild der Website und dem Builder. Übertragen Sie, was Sie benötigen, in gemeinsame Klassen und Seitenbereiche und löschen Sie dann den Ordner.',
    'Unpublished look changes' => 'Nicht veröffentlichte Änderungen am Erscheinungsbild',
    'visitors still see the published look.' => 'Besucher sehen weiterhin das veröffentlichte Erscheinungsbild.',
    'Preview the whole site' => 'Die ganze Website in der Vorschau ansehen',
    'Publish the look' => 'Erscheinungsbild veröffentlichen',
    'Discard the unpublished look changes?' => 'Die nicht veröffentlichten Änderungen am Erscheinungsbild verwerfen?',
    'Design system: %s' => 'Designsystem: %s',
    'no change' => 'keine Änderung',
    'Classes: %s' => 'Klassen: %s',
    'changed' => 'geändert',
    'Menus: %s' => 'Menüs: %s',
    'automatic' => 'automatisch',
    'Saved to the draft look – preview the whole site, then publish it.' => 'Im Entwurf des Erscheinungsbilds gespeichert – sehen Sie sich die ganze Website in der Vorschau an und veröffentlichen Sie sie dann.',
    'There was nothing to publish.' => 'Es gab nichts zu veröffentlichen.',
    'The look is published: %s' => 'Das Erscheinungsbild ist veröffentlicht: %s',
    'The unpublished look changes were discarded.' => 'Die nicht veröffentlichten Änderungen am Erscheinungsbild wurden verworfen.',
    'The earlier look is in the draft – preview the whole site, then publish it.' => 'Das frühere Erscheinungsbild liegt im Entwurf – sehen Sie sich die ganze Website in der Vorschau an und veröffentlichen Sie sie dann.',
    'The look version does not exist.' => 'Die Version des Erscheinungsbilds existiert nicht.',
    'Design tokens have been loaded into the draft look – preview the whole site, then publish it.' => 'Die Design-Tokens wurden in den Entwurf des Erscheinungsbilds geladen – sehen Sie sich die ganze Website in der Vorschau an und veröffentlichen Sie sie dann.',
    'Colours, fonts, sizes and shapes go to the draft look first – with changes of shared classes and menus. Visitors see them once you publish the look.' => 'Farben, Schriften, Größen und Formen gehen zuerst in den Entwurf des Erscheinungsbilds – zusammen mit Änderungen an gemeinsamen Klassen und Menüs. Besucher sehen sie, sobald Sie das Erscheinungsbild veröffentlichen.',
    'Earlier looks' => 'Frühere Erscheinungsbilder',
    'Each time you publish the look, the one before is kept here (the last 20).' => 'Jedes Mal, wenn Sie das Erscheinungsbild veröffentlichen, wird das vorherige hier aufbewahrt (die letzten 20).',
    'before: %s' => 'vorher: %s',
    'Back to this look' => 'Zu diesem Erscheinungsbild zurückkehren',
    'The menu is saved to the draft look – preview the whole site, then publish it.' => 'Das Menü ist im Entwurf des Erscheinungsbilds gespeichert – sehen Sie sich die ganze Website in der Vorschau an und veröffentlichen Sie sie dann.',
    'In the draft look the menu is again built automatically from pages in the navigation.' => 'Im Entwurf des Erscheinungsbilds wird das Menü wieder automatisch aus den Seiten der Navigation aufgebaut.',
    'In the draft look the footer menu is empty.' => 'Im Entwurf des Erscheinungsbilds ist das Fußbereich-Menü leer.',
    '%s (dark mode)' => '%s (Dunkelmodus)',
    'Heading font' => 'Überschriftenschrift',
    'Text font' => 'Textschrift',
    'Base font size' => 'Basisschriftgröße',
    'Type scale' => 'Schriftgrößenskala',
    'Text width' => 'Textbreite',
    'Custom fonts' => 'Eigene Schriften',
    'Logo left, menu right' => 'Logo links, Menü rechts',
    'The logo on the left, the menu and a button on the right. Stays at the top while scrolling.' => 'Das Logo links, das Menü und ein Button rechts. Bleibt beim Scrollen oben stehen.',
    'Centred logo' => 'Zentriertes Logo',
    'The logo in the middle with the menu below it – for a site led by the brand.' => 'Das Logo in der Mitte mit dem Menü darunter – für eine markengeführte Website.',
    'With a contact bar' => 'Mit Kontaktleiste',
    'A thin bar with the phone and e-mail above the logo and the menu.' => 'Eine schmale Leiste mit Telefon und E-Mail über dem Logo und dem Menü.',
    'Minimal' => 'Minimal',
