    'With a call to action' => 'Mit Handlungsaufforderung',
    'A coloured call to action above a two-column footer.' => 'Eine farbige Handlungsaufforderung über einem zweispaltigen Fußbereich.',
    'The news item and a call to action below it.' => 'Der News-Beitrag und darunter eine Handlungsaufforderung.',
